**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("trojkaty.txt");
    int n;
    plik >> n;
    double maxPole = -1;
    int maxIdx = -1;
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; i++) {
        int x1, y1, x2, y2, x3, y3;
        plik >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
        double pole = abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0;
        cout << "Trojkat " << i + 1 << ": wierzch. ("
             << x1 << "," << y1 << ")(" << x2 << "," << y2 << ")(" << x3 << "," << y3
             << ") -> pole = " << pole << endl;
        if (pole > maxPole) {
            maxPole = pole;
            maxIdx = i + 1;
        }
    }
    cout << "Najwieksze pole: trojkat " << maxIdx << ", pole = " << maxPole << endl;
    return 0;
}
```

**Wyjasnienie**: Pole trojkata z wspolrzednych wierzcholkow obliczamy wzorem na iloczyn wektorowy (wzor sznurowadla). Wartosc bezwzgledna jest konieczna, bo wynik moze byc ujemny w zaleznosci od kolejnosci wierzcholkow.

